    def bfs(src):
        D={src:0}; q=deque([src])
        while q:
            r,c=q.popleft()
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    if (dr,dc)==(0,0): continue
                    nr,nc=r+dr,c+dc
                    if 0<=nr<h and 0<=nc<w and g[nr][nc]!=0 and (nr,nc) not in D:
                        D[(nr,nc)]=D[(r,c)]+1; q.append((nr,nc))
        return D
    dist={}
    for r,c,v in ms:
        for cell,d in bfs((r,c)).items():
            if cell not in dist or d<dist[cell][0]: dist[cell]=[d,[v]]
